          3: { title: "Шаг 3 · Подписка и продолжение после ошибки", prompt: "Сопоставьте подписчиков с типом события и продолжите после сбоя одного обработчика. Ожидаемое наблюдение: один успешный вызов после сбоя.", starter: "class Dispatcher:\n    def __init__(self): self.handlers = {}\n    def subscribe(self, event_type, handler): self.handlers.setdefault(event_type, []).append(handler)\n    def dispatch(self, event_type, event):\n        succeeded = 0\n        for handler in self.handlers.get(event_type, []):\n            try: handler.handle(event); succeeded += 1\n            except Exception: print(\"Обработчик пропущен\")\n        return succeeded\n\nclass Broken:\n    def handle(self, event): raise RuntimeError(\"local failure\")\nclass Screen:\n    def handle(self, event): print(\"Получено:\", event)\n\ndispatcher = Dispatcher()\ndispatcher.subscribe(\"payment\", Broken())\ndispatcher.subscribe(\"payment\", Screen())\nprint(\"Успешно:\", dispatcher.dispatch(\"payment\", \"QR-1\"))" },
          4: { title: "Шаг 4 · Независимые обработчики", prompt: "Подключите аудит и уведомление через общий метод handle. Ожидаемое наблюдение: оба обработчика получили одно событие.", starter: "class AuditLogHandler:\n    def __init__(self): self.records = []\n    def handle(self, event): self.records.append(event)\nclass PassengerNotifierHandler:\n    def handle(self, event): print(\"Уведомление:\", event)\n\nevent = \"поездка разрешена\"\naudit = AuditLogHandler()\nfor handler in (audit, PassengerNotifierHandler()): handler.handle(event)\nprint(\"Записей аудита:\", len(audit.records))" },
          5: { title: "Шаг 5 · Проверки доставки", prompt: "Проверьте продолжение после ошибки и успешную доставку следующему подписчику. Ожидаемое наблюдение: оба assert проходят.", starter: "class Dispatcher:\n    def __init__(self): self.handlers = []\n    def subscribe(self, handler): self.handlers.append(handler)\n    def dispatch(self, event):\n        delivered = 0\n        for handler in self.handlers:\n            try: handler.handle(event); delivered += 1\n            except Exception: pass\n        return delivered\nclass Broken:\n    def handle(self, event): raise RuntimeError()\nclass Good:\n    def handle(self, event): self.seen = event\n\ngood = Good()\ndispatcher = Dispatcher()\ndispatcher.subscribe(Broken())\ndispatcher.subscribe(good)\nassert dispatcher.dispatch(\"notice\") == 1\nassert good.seen == \"notice\"\nprint(\"Ошибка изолирована; следующее событие доставлено\")" },
