  terminalContent.labs[4].analog = { title: "Заказ в кафе · независимые роли", explanation: "Кассир передаёт заказ кухне и журналу через отдельные зависимости; новый способ оплаты добавляется стратегией.", expectedOutput: "Кухня получила Обед", source: `class Kitchen:\n    def accept(self, order): return "Кухня получила " + order\nclass Journal:\n    def __init__(self): self.orders = []\n    def record(self, order): self.orders.append(order)\ndef place_order(order, kitchen, journal):\n    result = kitchen.accept(order); journal.record(order); return result\norder = "Обед"; journal = Journal(); print(place_order(order, Kitchen(), journal)); assert journal.orders == [order]` };
  terminalContent.labs[5].analog = { title: "Пропуск в музей · разные полномочия", explanation: "Бесплатный пропуск подтверждает право входа, но не притворяется платёжным счётом; общий сценарий использует только валидность.", expectedOutput: "Вход разрешён", source: `class MuseumPass:\n    def is_valid(self): return True\nclass PaidPass:\n    def __init__(self, balance): self.balance = balance\n    def is_valid(self): return self.balance > 0\ndef enter(passport): return "Вход разрешён" if passport.is_valid() else "Отказ"\nprint(enter(MuseumPass()), enter(PaidPass(100))); assert not hasattr(MuseumPass(), "charge")` };
  terminalContent.labs[6].analog = { title: "Заказ-наряд · фабрика и пошаговая сборка", explanation: "RepairOffice создаёт документ через Factory Method, а Builder собирает обязательные номер и исполнителя до выдачи.", expectedOutput: "Наряд WO-1 готов", source: `class WorkOrder:\n    def __init__(self, number, person): self.number, self.person = number, person\nclass WorkOrderBuilder:\n    def __init__(self): self.number = ""; self.person = ""\n    def set_number(self, value): self.number = value; return self\n    def set_person(self, value): self.person = value; return self\n    def build(self):\n        if not self.number or not self.person: raise ValueError("нужны номер и исполнитель")\n        return WorkOrder(self.number, self.person)\nclass Office:\n    def create_order(self): raise NotImplementedError\nclass RepairOffice(Office):\n    def create_order(self): return WorkOrderBuilder().set_number("WO-1").set_person("Алия").build()\norder = RepairOffice().create_order()\nprint("Наряд", order.number, "готов"); assert order.person == "Алия"` };
  terminalContent.labs[7].analog = { title: "Складской адаптер единиц", explanation: "Адаптер преобразует килограммы в граммы для отдельного интерфейса датчика, используя одну величину и явный коэффициент.", expectedOutput: "150000 г", source: `class Scale:\n    def read_grams(self, grams): return str(grams) + " г"\nclass KilogramAdapter:\n    def __init__(self, scale): self.scale = scale\n    def read(self, kilograms): return self.scale.read_grams(kilograms * 1000)\nprint(KilogramAdapter(Scale()).read(150))` };
  terminalContent.labs[8].analog = { title: "Проверка брони и уведомления", explanation: "Цепочка проверяет бронь и вместимость по очереди; экран и счётчик независимо получают готовое решение.", expectedOutput: "Экран: разрешено", source: `def check(confirmed, seats, guests):\n    if not confirmed: return "отказ: бронь"\n    if guests > seats: return "отказ: места"\n    return "разрешено"\nclass Screen:\n    def update(self, result): print("Экран:", result)\nclass Counter:\n    def update(self, result): self.last = result\nresult = check(True, 20, 12); counter = Counter(); Screen().update(result); counter.update(result)\nassert counter.last == result` };
  terminalContent.labs[9].analog = { title: "Заявка на ремонт · сценарий через порт", explanation: "Модель содержит предметные поля, use case зависит от порта сохранения, а адаптер реализует его отдельно.", expectedOutput: "Заявка сохранена: BUS-17", source: `class RepairRequest:\n    def __init__(self, bus, issue): self.bus, self.issue = bus, issue\nclass MemoryRequestRepository:\n    def __init__(self): self.items = []\n    def save(self, request): self.items.append(request)\nclass SubmitRequest:\n    def __init__(self, repository): self.repository = repository\n    def run(self, request): self.repository.save(request); return "Заявка сохранена: " + request.bus\nrepository = MemoryRequestRepository(); print(SubmitRequest(repository).run(RepairRequest("BUS-17", "шум"))); assert len(repository.items) == 1` };


